using System.Collections.Generic;

namespace LiveRaid.Client
{
    /// <summary>English names and descriptions of every F12 setting, by "section|key" (generated once from Settings.cs; the Russian ones stay beside the Bind calls).</summary>
    internal static class LocEn
    {
        public static readonly Dictionary<string, (string name, string desc)> Entries = new Dictionary<string, (string, string)>
        {
            ["0. Compact menu|Menu status"] = ("Status", "Who controls the settings in LiveRaid Online"),
            ["1. Main|Developer mode"] = ("Developer mode", "Show every setting on its own instead of only the packs and levels. A pack with custom values shows \"Custom\""),
            ["0. Compact menu|Keys and doors pack"] = ("Keys and doors", "Real keys on bots, help at doors and when stuck, locked containers"),
            ["0. Compact menu|Keys carried"] = ("Keys on bots", "How many keys to this map's doors the bots carry. Few: PMCs 30 %, scavs 10 %, up to 2 keys. Like online: 60 % / 25 %, up to 3. Many: 85 % / 45 %, up to 4"),
            ["0. Compact menu|Prize keys"] = ("Prize keys on PMCs", "The key to the richest place on the map (marked room, KIBA, Labs card...) sits in a PMC's pouch - it can be neither seen nor taken. Rare: 40 % per raid. Usual: 75 %. Often: always. Each further carrier in the raid is less likely"),
            ["0. Compact menu|Map life pack"] = ("Moving over the map", "Bots walk the whole map like players: their own exploration quests, hot zones, key places, hot drop, no idling and no long stands"),
            ["0. Compact menu|Move out after (min)"] = ("Move out after, min", "A leader or solo that has hung about one district (~120 m) this many minutes moves to the other end of the map. 0 = off (3 at least)"),
            ["0. Compact menu|Learning pack"] = ("Learn from my routes", "The mod remembers where you walk and sends bots to those places (from the next raid). Shortcuts through found climbs are in developer mode only"),
            ["0. Compact menu|Characters pack"] = ("Bot characters", "Every bot has its own style (camper, rat, rusher, looter, quester...) and a skill level from newcomer to pro"),
            ["0. Compact menu|Extract pack"] = ("Extraction like online", "Every squad has its own time to leave, hardly anyone leaves in the first 20 minutes, exits of their own side of the map, switches, the whole squad leaves together"),
            ["0. Compact menu|Spawn pack"] = ("Spawns like online", "An online-sized PMC lobby, random free points (a squad can appear close by), squads spread over the map sides"),
            ["0. Compact menu|Extra PMCs"] = ("PMCs above the online lobby", "How many PMCs to add to the map's online lobby at the start; the mix has more solos. 0 = exactly the online lobby (from the next raid)"),
            ["0. Compact menu|Loot pack"] = ("Loot like a player", "Bots weigh value and risk, do not loot under fire, search bodies after a fight and a whole room, drop cheap things for a find"),
            ["0. Compact menu|Squads pack"] = ("Squads", "Roles in a squad, staying together, waiting for mates, running to help, formations, voice calls, flanks, swapping meds and loot"),
            ["0. Compact menu|Fight pack"] = ("Fight tactics", "Morale and roles in a fight, reaction to far gunfire, return fire, fighting at the range of their own weapon, searching at a normal pace"),
            ["0. Compact menu|Leave a lost fight"] = ("Flee a lost fight", "Against a clear odds a bot may lose its nerve and leave the fight. Rarely / Usual / Often - how readily"),
            ["0. Compact menu|Forget a cold fight"] = ("Forget a cold fight", "An enemy not seen or heard for long is dropped and the bot goes back to its business. Fast / Usual / Long - how long it looks for him"),
            ["0. Compact menu|Healing pack"] = ("Healing", "Bandaging in the first quiet minute, healing broken off under fire, splints and painkillers for legs, surgery from the backpack"),
            ["0. Compact menu|EFT fixes pack"] = ("EFT AI fixes", "Fixes bugs of EFT and the mods: stuck hands and reloading, thrown away magazines, flickering weapon swaps, friendly fire inside a squad"),
            ["0. Compact menu|Summoned ammo (rounds per stack)"] = ("Ammo from nowhere, rounds per stack", "A loose stack on demand: PMCs get it into the secure container, scavs into the rig or a pocket; for a found gun - one spare magazine. 0 = off (as in SPT)"),
            ["0. Compact menu|Quests pack"] = ("EFT quests", "PMCs go to the steps of their quests and act them out (pick up, plant, inspect), squads split over different quests, quest points are checked"),
            ["0. Compact menu|Routes pack"] = ("Routes through obstacles", "Bots walk recorded routes (routes/<map>.json) where the navmesh does not lead: rubble, railings, the \"Cliff\""),
            ["1. Main|Log detail"] = ("Log detail", "Usual: the \"LR ...\" lines in the BepInEx log. Detailed: also a raid trace file in BepInEx/plugins/LiveRaid/logs (every decision, what each bot does every 15 s, stuck bots, system health every minute). Full: like detailed, plus everything into the BepInEx log and every 5 s (heavy, for hunting a bug). From the next raid"),
            ["1. Main|Log network and frame time"] = ("Network and frame log", "Every 10 s: this machine's frame time (fps, worst frame, frames over 100/250 ms) and, on a Fika host, each player's latency, the reliable packet queue, losses. A line goes to the log when something is wrong (latency or a frame over 250 ms, a queue), otherwise to the trace. Tells a lagging host from a bad line"),
            ["1. Main|Raid summary when the game is closed"] = ("Raid summary on quitting", "If the game is closed in the middle of a raid, the raid summary (LR Health on, the encounter log) is still written; every 5 minutes an interim summary goes to the trace"),
            ["1. Main|Coverage log"] = ("Map coverage log", "Every 10 s the bots' positions into BepInEx/plugins/LiveRaid/coverage/*.csv - to check that bots cover the whole map (tools/coverage.py)"),
            ["1. Main|Encounter log"] = ("Encounter log", "Raid measurements: number of bots, hostile groups in sight, first meeting, reactions to gunfire. Files in BepInEx/plugins/LiveRaid/encounters (tools/encounters.py)"),
            ["1. Main|Harmonize behaviour"] = ("Make the mods agree", "The mods do not pull a bot two ways: the loot search runs in the background (the bot does not freeze every few seconds), QuestingBots gives way when there is loot and skips its loot break if nothing valuable is within 40 m; a bot darting between two behaviours calms down for a while"),
            ["1. Main|Smooth decisions"] = ("Smooth decisions", "One picture of a bot's situation: danger is noticed at once, calm comes back gradually (8 s after a glance or a hit, 10-25 s after a fight). Errands, detours and reactions to a far fight begin only in real calm. Off: the old instant checks (for comparison, see \"LR Brain on\")"),
            ["2. Keys and locked doors|Real keys only"] = ("Real keys only", "Bots open locked doors only with a key that really lies in their inventory. Keys are issued at spawn and can be taken off a body"),
            ["2. Keys and locked doors|PMC key chance"] = ("PMC key chance", "The chance that a PMC spawns with at least one key to a door of this map"),
            ["2. Keys and locked doors|Scav key chance"] = ("Scav key chance", "The chance that a scav spawns with a key to a door of this map"),
            ["2. Keys and locked doors|Max keys per bot"] = ("Most keys per bot", "How many keys to this map one bot may carry"),
            ["2. Keys and locked doors|Door manners"] = ("Doors like players", "After going into a building a bot sometimes shuts the door behind it (if no mates are left at the door); coming to a shut door it freezes for 1-2 s to listen. Rats and disciplined squads more often, rushers hardly ever"),
            ["2. Keys and locked doors|Unstick bots (doors, door leaves, corners)"] = ("Help at doors and corners", "A bot standing 2 s at a shut door on its way opens it; stuck again - it backs off and passes once more; after two failures it leaves the door alone for a minute (EFT bots open only doors that have a link in the navmesh)"),
            ["2. Keys and locked doors|Free bots shut in a room"] = ("Let bots out of a room", "A bot whose every path fails at once (three quest steps or loot unreachable within 2.5 min) opens the nearest shut door, and without one - while nobody is looking - moves to the last point of its path outside"),
            ["2. Keys and locked doors|Back off and re-route when stuck again"] = ("Back off and re-route when stuck", "If help at the door did not free the bot (stuck again within 90 s at the same place) it backs off along its own trail and builds a path round; then a longer back-off, then it drops the errand"),
            ["2. Keys and locked doors|Use keys found in the raid"] = ("Use a found key", "A key taken off a body or found in a box, to a locked door or container of this map - the bot wants to get there for 10 minutes (room x3, container - on the way)"),
            ["2. Keys and locked doors|Open locked containers with keys"] = ("Unlock containers with keys", "A bot with a key to a locked safe, case or trunk may go to it (by greed, once per container), unlock it and loot it"),
            ["2. Keys and locked doors|Prize keys in a PMC secure container"] = ("Prize keys", "Like online, a PMC may spawn with the key to the richest place of the map (the marked room on Customs, KIBA on Interchange, the marked ones on Reserve, the Labs card...). The key sits in a pouch: it can be neither seen nor taken. Most likely the bot runs there first - at once, a little later or at the end of the raid"),
            ["2. Keys and locked doors|Prize key chance"] = ("Prize key chance", "The chance that one PMC of the raid carries a prize key"),
            ["2. Keys and locked doors|Prize key chance drop per carrier"] = ("Chance drop per carrier", "Each next carrier in the raid is that much less likely (0.75: the first 75 %, the second 55 %, the third 35 %, the fourth 15 %)"),
            ["3. Map-wide movement|Wait out the BTR only briefly"] = ("Wait out the BTR only briefly", "EFT sends every bot near the BTR into cover until the vehicle is gone - at its stops that is minutes. Here a bot gives way for 20-35 s (rats and campers a little longer), then is busy with its own affairs for 3 minutes; closer than 12 m to the vehicle it still backs away"),
            ["3. Map-wide movement|Never stand idle"] = ("No idling", "A bot that has not moved for 40 s in a layer that does nothing itself (QuestingBots recovery, patrol, LootingBots without loot, a follower without a leader) and has no reason to stand (healing, loot, a task, an exit timer) is told to go; after 75 s it is sent to another part of the map (LR Idle)"),
            ["3. Map-wide movement|Map-wide quests"] = ("Quests over the whole map", "Exploration and loot goals over the whole map from the navmesh and the loot spots (cached per map)"),
            ["3. Map-wide movement|All loot spawn spots"] = ("All loot spots from the database", "Bot routes use all the loose loot spots of the map from the SPT database (all floors and rooms), not only the loot of the first raid. Applies when the map cache is built: after changing it delete BepInEx/plugins/LiveRaid/cache/<map>.json"),
            ["3. Map-wide movement|Region size (m)"] = ("District size, m", "The size of one exploration district; smaller - more and shorter trips"),
            ["3. Map-wide movement|Exploration desirability"] = ("Exploration desirability", "The base desirability of exploration goals (EFT quests - 50)"),
            ["3. Map-wide movement|Scavs roam the map"] = ("Scavs roam the map", "AI scavs take exploration goals over the whole map like PMCs. Turning it on turns \"Scavs patrol their area\" off; both off - scavs as in plain SPT"),
            ["3. Map-wide movement|Scavs patrol their area"] = ("Scavs patrol their area (like online)", "AI scavs, as online, keep to the area where they appeared (70-120 m, growing if there is nothing to do): they walk it with short stops, go to noise and gunfire close by and come back, call the neighbours of their area into a fight. Player scavs are not affected. Turning it on turns \"Scavs roam the map\" off; both off - scavs as in plain SPT"),
            ["3. Map-wide movement|Player scavs play like online"] = ("Player scavs like online", "A player scav comes in later (as QuestingBots does), its raid is short - 7-15 min (a looter 10-18), then to the exit; after a fight it runs to PMC bodies once it is quiet there; it does not join PMC fights (waits for the winner or leaves), except every eighth \"chad scav\" who hunts PMCs; it killed an AI scav - the scavs nearby are its enemies"),
            ["3. Map-wide movement|Keep to cover across open ground"] = ("Skirt open ground", "If 40+ m of open ground lies ahead (a field, the middle of a road) a careful fighter runs along the edge - to cover 15-35 m to the side, if the path is longer by no more than a third; after gunfire close by almost everyone does, a rusher in a quiet raid goes straight"),
            ["3. Map-wide movement|Head on a swivel"] = ("Head on a swivel", "A wary fighter (heard an enemy, a recent fight) keeps glancing at doors, openings and toward the enemy or noise while walking, not only where it is going"),
            ["3. Map-wide movement|Look over open ground first"] = ("Look over open ground first", "Before crossing a field or a wide open street a careful fighter looks it over from cover for 2-4 s (not every time and not every fighter)"),
            ["3. Map-wide movement|Spread the bots over the map"] = ("Bots spread over the map", "A soft adjustment: a quest (district, key place, room) in a part of the map where there are more bots than due weighs less, in an empty part more; a bot sent \"elsewhere\" picks the crowded place less often. Nobody is moved by force, bosses and airdrops are left alone. A district's due share grows with its loot and shifts at random each raid (see \"Unevenness\"): exactly even never happens"),
            ["3. Map-wide movement|Spread strength, %"] = ("Spread strength, %", "How strongly a crowded district repels and an empty one lures. 0 - off, 50 - a district three times as busy as due weighs half, 100 - strong (down to 0.4 and up to 2.2 times). Each squad follows it by character: explorers more willingly, campers, snipers and questers less"),
            ["3. Map-wide movement|Spread unevenness, %"] = ("Spread unevenness, %", "How far this raid's due share of the districts differs from \"by loot value\": 0 - strictly by value, 35 - a noticeable tilt to one or two parts of the map (changes every 6 minutes), 100 - strong"),
            ["3. Map-wide movement|Long gun takes the high ground"] = ("Long gun on the high ground", "A squad member with a long gun from time to time briefly (15-30 s) takes a height above the squad's route and covers it, then catches up"),
            ["3. Map-wide movement|Airdrop fights"] = ("Airdrop as an event", "Not everyone goes to a landed airdrop, but up to three squads: those close by (up to ~220 m) that have the time in the raid, the strength (health) and the wish by character and doctrine - the fight happens there"),
            ["3. Map-wide movement|Walk where people walk"] = ("Walk where people walk", "PMCs and player scavs on a long way step onto \"people's corridors\" - where you walk (your recorded routes) and where people walk online: from the spawn to key places and hot districts, from there to the exits. No more than a third of extra path; a path already along a corridor is not changed. So paths cross and meetings happen on the road, not only at random loot"),
            ["3. Map-wide movement|Corridor pull, %"] = ("Corridor pull, %", "How willingly bots step onto the corridors (50 = explorers ~65 %, rats ~20 % of far paths) and how much more wanted the districts with corridors are"),
            ["3. Map-wide movement|Tempo like players"] = ("Tempo like players", "Fast squads (by doctrine: assault, PvP hunters) linger less in one place and at quest points; a bot in an already searched district (by itself lately or by many others), after 2-3 min without loot or a fight, leaves for another part of the map; a bot not greedy for loot looks around for it more briefly. Looters and questers - as before"),
            ["3. Map-wide movement|Hot zones"] = ("Hot zones", "Districts rich in loot (industrial zone, dorms, malls...) draw looters and aggressive squads, especially in the first minutes; districts that another squad has just passed or the bot has cleaned out itself lose interest for a while"),
            ["3. Map-wide movement|Move on across the map"] = ("Move on across the map", "A squad or solo that has been in one place (an explorer ~3 min ... a camper ~8) goes on: goals nearby lose their appeal for a while, far ones gain"),
            ["3. Map-wide movement|Move bots out of a place they stay in too long"] = ("Evict those who sit too long", "A leader or solo that has hung about one district (~120 m) for the set time drops its current goal, everything near becomes uninteresting for 8 minutes, and if it still stands it is ordered to a far place of the map. Off: bots decide for themselves"),
            ["3. Map-wide movement|Stay limit in one area (min)"] = ("Limit in one district, min", "How long a bot may stay in one district (explorers and rushers a little less, rats and snipers a little more)"),
            ["3. Map-wide movement|Short holds on QuestingBots quests"] = ("Short holds on QuestingBots quests", "In QuestingBots' standard quests (the dorms on Customs and others) ambush and hold steps run 30-120 s - the bots stood like campers. Here 5-15 s (ambush 8-15 s). Bosses and their guards - as in the original"),
            ["3. Map-wide movement|Hot-drop rushers"] = ("Hot drop", "A part of the PMCs (mostly looters and rushers, 1 of 4-5) run from the spawn to the richest place of the map - the dorms on Customs, the bunker on Reserve - like players online. The first 6 minutes"),
            ["3. Map-wide movement|Key places draw a third of the PMCs"] = ("Key places", "A few places where players run online (dorms, bunkers...) get quests of their own with goals on every floor. About a third of the PMC squads pick one of them, evenly over the places; the others go there a little less often than to other places"),
            ["3. Map-wide movement|Thorough looting"] = ("Search after a goal", "Having finished a goal, a bot may comb the surroundings for loot (by character and the wealth of the place) instead of running straight to the next point"),
            ["3. Map-wide movement|Learn places from my route"] = ("Record my route", "In the background each raid records where you walk. Places that are not on the bots' map and that they can reach go to learned/<map>.json; climbs joining places the navmesh does not join are route candidates (learned/<map>.shortcuts.json). Delete learned/<map>.json to forget the map"),
            ["3. Map-wide movement|Bots visit places from my routes"] = ("Bots visit my places", "Exploration quests send bots to places from your routes too (from the next raid). Off: places are recorded but not used"),
            ["4. Bot characters|Moods over the raid"] = ("Moods over the raid", "Every bot may have a nature of its own: a vengeful one looks for whoever shot at it; one that barely survived turns careful and leaves earlier; after a streak of kills - a high (bolder but sloppier); with expensive loot - guards it, avoids fights and hurries to the exit. Not everyone and not everything"),
            ["4. Bot characters|Flee when the squad is wiped"] = ("Flee when the squad is dead", "The last one alive of a squad (2+) with a high chance drops the fight and leaves for the exit - everyone has the instinct of self-preservation"),
            ["4. Bot characters|Characters"] = ("Characters", "Every bot has a play style (camper, rat, rusher, looter, quester, explorer, hunter, sniper), from it SAIN's personality and the choice of goals"),
            ["4. Bot characters|Skill spread"] = ("Skill spread", "Bots from newcomer to pro: aiming speed, spread, sight and hearing are each their own"),
            ["4. Bot characters|Memory multiplier"] = ("Enemy memory, x", "How many times longer bots remember an enemy before dropping him (further on - by character)"),
            ["4. Bot characters|Max wait before searching, s"] = ("Wait before searching, s", "SAIN lets a bot go and check on an enemy only when he has not been heard for the personality's time (rat 240 s, \"turtle\" 90, \"chad\" 16), and every shot close by resets the count. This is a ceiling (+-20 %) so that even rats move again after a couple of quiet minutes. 0 = as in SAIN"),
            ["4. Bot characters|Personal extract time"] = ("Own time to leave", "Each squad leaves at its own moment: some early, most in the middle, campers late. A full backpack still drives a bot home earlier (SAIN)"),
            ["4. Bot characters|Online-like extract times"] = ("Leave times like online", "As online, hardly anyone leaves in the first 20 minutes (or the first half of a short raid): the early moment fires only by lot - 3 % at the start, 20 % by the 20th minute (60 % for the badly wounded without healing or those who lost half the squad), otherwise it shifts later, mostly to ~70 % of the raid"),
            ["4. Bot characters|Leave through switch exits"] = ("Exits with a switch", "Some PMC squads leave through an exit that a switch opens (Interchange, the bunker and D-2 on Reserve, the Labs gate...): they run to the switch, pull it (or find it already on), go to the exit, stand the timer and leave"),
            ["3. Map-wide movement|Leave the raid early when it is time"] = ("Leave early when it is time", "A PMC weighs its state, loot and the situation: wounded without meds, a backpack of valuables, the squad lost half, a long raid with loot - and may leave before its own time. Off: only the personal time"),
            ["3. Map-wide movement|Strip the bodies before leaving"] = ("Search the bodies before leaving", "A PMC that is due to leave with an unsearched body of a fallen mate or its victim nearby searches it first (up to 4 minutes, only in quiet). Not when it must leave at once (no ammo, badly wounded without healing)"),
            ["8. Squads|Leave the raid together"] = ("Leave as a whole squad", "The leader decides when to leave and everyone goes with him to HIS exit; followers do not leave on their own. The exit timer starts when the squad has gathered (within 15 m, waiting 90 s at most)"),
            ["8. Squads|Paid and conditional exits"] = ("Paid and special exits", "Bots leave through exits with a condition too if they meet it like a player: a car - if they have the roubles (the server gives half of the PMCs 6-40k in a pouch), an exit without a backpack, a descent down a rock and the like - by the game's own check. Switch exits - as before, joint ones, the train and events are not available to bots"),
            ["8. Squads|Leave when standing at the exit"] = ("Exit counted at the point", "The game starts a bot's exit timer only within 1 m of the exit point; at some exits a bot stops 1-4 m short (a fence, a kerb) and stands. After 3 s at the very point the timer runs and the bot leaves (the squad still waits for each other)"),
            ["8. Squads|Wait at the exit like a player"] = ("Wait at the exit like a player", "Having reached the exit point a bot crouches and looks the way it came while the timer runs. The game made it look at a point inside its own head - the bot twitched on the spot"),
            ["8. Squads|Paid car drives off"] = ("Paid car drives off", "A bot leaving by a paid car (the A exit by the dorm and the like) starts its count like a player who paid the driver: after the exit time the car drives off and the exit is closed for everyone. In Online the count and the departure are run by Fika for all players; in single player the car does not leave if you are in it"),
            ["8. Squads|Exits of the spawn side"] = ("Exits of its own side", "A PMC leaves through an exit of the side where it spawned, like a player (on Customs: ZB-1011, ZB-1012, Old gas station on one side; Crossroads, Trailer park, Checkpoint, Smuggler's boat on the other); near ones more likely, a far one now and then. EFT sent everyone to the nearest exit of the map"),
            ["6. Spawns|Online-like spawns"] = ("Spawns like online", "On: PMC and player-scav groups appear at a random free point, so a squad may appear close to you, as online. Off: QuestingBots' safe mode - groups as far as possible from everyone"),
            ["6. Spawns|PMCs use every player spawn point"] = ("Every player spawn point", "QuestingBots puts PMCs only on the \"Player\" points of their side. With this - on the points of groups/the other side and on the points the game itself marks for PMC bots too. Never on your point or closer than 25 m to it"),
            ["6. Spawns|Spread squads over the map sides"] = ("Spread squads over the sides", "As online, the lobby is divided over the map: long maps (Customs, Shoreline, Lighthouse) into two halves, the rest into four quarters. Each squad goes where there are fewer PMCs"),
            ["6. Spawns|Bigger lobby"] = ("Bigger lobby than online", "More PMCs from the start (the number below), with more solos: about 45 % of the groups are solos, the rest pairs to fives. Off: the online lobby size. From the next raid"),
            ["6. Spawns|Extra PMCs at raid start"] = ("Extra PMCs", "How many PMCs to add to the map's online lobby"),
            ["6. Spawns|Min distance at raid start (m)"] = ("Min distance at start, m", "The closest a group may appear to another player at the start of a raid (QuestingBots: 30). Later in the raid - QuestingBots' distance"),
            ["6. Spawns|Online-sized lobby"] = ("Lobby like online", "PMCs at the start = the map's online lobby (between min and max players), all at once; only reserves come in later"),
            ["6. Spawns|Reserve PMCs"] = ("Reserve PMCs", "How many PMCs come in later when the PMCs of the starting lobby die (needs a game restart)"),
            ["6. Spawns|Players of the group take lobby places"] = ("Group players take places", "Co-op (LiveRaid Online): every PMC player of the group beyond the first takes the place of one PMC bot, as in an online lobby (4 players on Customs - 3 bots fewer). Easier for the host. Single player - no effect"),
            ["6. Spawns|Lively map"] = ("Lively map", "Player scavs come on their own schedule from one and a half minutes into the raid (2-5 at a time), not only when half the PMCs are dead and all the reserves have come in; in co-op 2 more reserve PMCs for every player beyond the first"),
            ["6. Spawns|Player scavs as replacements"] = ("Player scavs as replacements", "When PMCs are dead or gone and the \"people\" (PMCs, player scavs, you and your group) are fewer than the share of the lobby, the nearest player-scav group on the schedule comes in before its time - until the last minutes of the raid. No new bots are made (QuestingBots' groups are scheduled for the whole raid), the cap of player scavs at once is the \"Lively map\"'s. After a loud fight they come sooner and from its side of the map (not closer than 150 m to a player). Needs \"Lively map\""),
            ["6. Spawns|People share of the lobby, %"] = ("People share, %", "How many \"people\" to keep on the map out of the lobby until the last minutes begin. Applies when \"Smart population balance\" is off (when on, it changes the share over the raid and by the map itself)"),
            ["6. Spawns|Smart population balance"] = ("Smart population balance", "How many PMCs, player scavs and AI scavs the map holds - neither a crowd nor a desert. Start: the online lobby of this very map (by its size and how closed it is) instead of one common number. Each raid has its own mood (quiet / usual / busy - one raid in four is quieter, one in four busier). Making up for the fallen: the people share depends on the age of the raid (hardly anyone is added at the beginning, fewer and fewer towards the end; big open maps keep more people), and a bit more if the whole map has been quiet for long. Comfort: if there are too many bots within 120 m of a human (or the free camera), no new ones come in and AI scav waves are held back. Only numbers change: nobody is sent to you and no events are pushed to you. Part of it works from the next raid"),
            ["6. Spawns|Population density, %"] = ("Population density, %", "100 - like the map's online lobby, 70 - quieter (fewer bots and people), 130 - denser. Affects the start, the people share and the AI scav ceiling"),
            ["6. Spawns|Follow the lobby of the map, %"] = ("Follow the map's lobby, %", "How far the PMC count at the start is pulled from the common number (QuestingBots + \"Bigger lobby\") to this map's online lobby: 0 - leave alone, 100 - exactly the map's lobby"),
            ["6. Spawns|Comfort cap: bots near a human"] = ("Crowd cap near a human", "How many bots within 120 m of a human (or of the free camera) are still tolerable: at this number no new player scavs come in and AI scav waves are held back; they go on when it is 2 fewer"),
            ["7. Looting like a player|Think before looting"] = ("Think before looting", "Bots weigh the visible value of a body (full kit or a bum) against danger (recent shots, an unknown killer close by, open ground, their own gear, the squad). They loot at once (their own victims almost always), come back later or drop a body not worth the trip. No ambushes at the body"),
            ["7. Looting like a player|No looting in danger"] = ("No looting in danger", "PMCs and scavs stop looting (and do not start) when it is unsafe: a hit or fire at them, shots within 50 m, an enemy in sight or heard close by, a stranger within 50 m who is heard. They go back to looting 6 s after the last sign of danger. Mates and allies do not count"),
            ["7. Looting like a player|Loot while hurt without meds"] = ("Loot while hurt without meds", "LootingBots allows looting only when there is nothing to heal; a bot with a wound and no medkit never looted for the rest of the raid. Here it loots while there is nothing to heal with (with a medkit - it heals first)"),
            ["7. Looting like a player|Clean up after a fight"] = ("Clean up after a fight", "After a fight a squad (or a solo) searches the place: its own victims, those killed by mates, a fallen mate's body and everything valuable within 50 m. In quiet the bot goes to the most important and nearest; what was interrupted it continues later (up to 5 times in 8 minutes). The leader waits while mates search"),
            ["7. Looting like a player|Notice bodies nobody has searched"] = ("Notice unsearched bodies", "A bot that sees an unsearched body (ahead up to 45 m or within 12 m around) judges it like a player: weapon, armour, helmet, rig, PMC or scav - a backpack is almost always worth a look. Yes - the body becomes its task (in quiet). Each body is judged by a bot once"),
            ["7. Looting like a player|Bots go for the loot they are given"] = ("Go for the loot they are given", "Scavs' LootingBots layer has the same priority as QuestingBots' waiting layer - a scav handed a body stood and left (7 of 63 searched). Here QuestingBots' waiting layer gives way as soon as LootingBots has a target"),
            ["7. Looting like a player|Search the whole room"] = ("Search the whole room", "Having looted something, a bot goes through the rest of the room like a player hoping for something fat: every container within 12 m on this floor (up to 6, 2.5 minutes per room), if it is quiet and there is space"),
            ["7. Looting like a player|Weight matters"] = ("Weight matters", "From 45 kg a bot drops heavy and cheap-per-kilo things for a find (not only per slot), from 60 kg it leaves the raid noticeably earlier"),
            ["7. Looting like a player|Shed weight to run"] = ("Shed weight to run", "A bot so loaded that it cannot run (EFT overweight) in a lull has a chance to lay out the cheapest-per-kilo things from its backpack, rig and pockets until it can run again. It does not touch meds, grenades, keys, money, ammo and magazines for its own guns, a fallen mate's gear and weapons that it is carrying out (the cheap-by-weight of his things is fine)"),
            ["7. Looting like a player|Chance to shed weight, %"] = ("Chance to shed weight, %", "One roll per overweight spell of a bot: the greedy less often, the careful more often"),
            ["7. Looting like a player|Drop cheap stuff for a better find"] = ("Drop cheap stuff for a find", "A find (15k and up) does not fit: the bot throws out the cheapest if together it is worth no more than 40 % of the find (never meds, ammo, magazines, grenades, keys, quest items, money). With a full backpack it still goes to a body worth 50k+ within 30 m"),
            ["7. Looting like a player|Loot speed x"] = ("Loot speed, x", "How many times faster than LootingBots the bots search and take things (the pause after a thing, looking over, the delay before starting). 1 = as in LootingBots"),
            ["7. Looting like a player|Loot from the right side of the wall"] = ("Loot from its own side of the wall", "LootingBots put the spot to loot from at the nearest navmesh to the thing - by a cupboard under a thin wall that is often the next room: the bot ran into the wall and gave the thing up or looted through the wall. Now a spot from which the thing cannot be seen through a wall, or that has no path, is moved to the thing's side, and without one the thing is skipped"),
            ["7. Looting like a player|Squat still while looting"] = ("Do not spin while looting", "A bot at a body or container no longer turns on the spot (LootingBots re-aimed at the thing underfoot on every swing of the animation) and counts 1.6 m as close enough"),
            ["7. Looting like a player|Loot lying down (test)"] = ("Loot bodies lying down (TEST)", "TEST FEATURE. Coming to a BODY a bot, with the chance below, first lies down, then loots it lying and gets up; otherwise it crouches as before. Containers and things on the ground are always looted crouching. Nowhere to lie (slope, wall, water) - it crouches. Off: always crouch"),
            ["7. Looting like a player|Chance to lie down at a body, %"] = ("Chance to lie down at a body, %", "TEST FEATURE. The chance a bot lies down before searching a body (a roll per body). 50 = half lying, half crouching, 0 = always crouch, 100 = always lying"),
            ["8. Squads|Squad tactics"] = ("Squad tactics", "Roles in a PMC squad (leader, point, cover, shooter, rear - reassigned when the leader dies), looting a place together, helping a mate in a fight, quests to the taste of the whole squad"),
            ["8. Squads|Stay together"] = ("Stay together", "Followers keep close like a squad of players: 4-12 m moving (QuestingBots: 7-20), 8-22 m in a fight (15-35); the leader waits for stragglers beyond 10 m and gathers beyond 18 m; nobody goes beyond 30 m for loot or 25 m on an errand"),
            ["8. Squads|Wait for squadmates who loot"] = ("Wait for mates who loot", "The leader does not leave while a mate loots close by: waits (and goes back to those who strayed 20+ m) 100-190 s (40 s if the looter is beyond 25 m), then calls - looting stops, they follow"),
            ["8. Squads|Squad loot spread, m"] = ("Squad loot spread, m", "How far apart mates spread while looting. The first to start sets the squad's point; everyone loots within half of this from it. QuestingBots lets a follower loot this far from the leader (it was 30 m)"),
            ["8. Squads|Drop everything to help a squadmate"] = ("Drop everything to help a mate", "When a mate is being shot at or is in a firefight the others drop what they do (loot, quest steps, errands) and run to him (those close by take his enemy at once)"),
            ["8. Squads|Recover the loot of a fallen squadmate"] = ("Recover a fallen mate's loot", "When a mate has died and it is quiet the nearest goes to the body and takes as much as fits; if it does not fit - first hides its own cheap things nearby (a bush, a corner)"),
            ["8. Squads|Carry out the whole kit of a fallen squadmate"] = ("Carry out a mate's whole kit", "On top of \"Recover a fallen mate's loot\": a mate takes all the main gear of the fallen (weapon, armour, helmet, backpack - the backpack goes into its own whole, if the game lets it) and the expensive personal things he came into the raid with; for that it drops its own finds at the body (not gear and not its own kit: meds, ammo, magazines, keys stay), a friend's gear and things weigh double. What does not fit - hidden in bushes by the chance below, otherwise it goes almost at once to the exit. Off - as before"),
            ["8. Squads|Chance to hide the rest of a fallen squadmate loot in a bush, %"] = ("Chance to hide a mate's loot in a bush, %", "For a mate's whole kit: the chance that a friend's loot that did not fit is carried off and hidden in a secluded place nearby (a bush if there is one, else a corner or rubble); otherwise the bot goes almost at once to the exit with what fit"),
            ["8. Squads|How far to look for a bush for a fallen squadmate loot, m"] = ("Bush search range for a mate's loot, m", "How far from a mate's body a bot looks for a bush (or another secluded place) to hide his loot that did not fit. More - it finds a bush more often but walks longer"),
            ["8. Squads|Formation"] = ("Formation", "Followers keep places in a formation round the leader (a column in buildings) instead of all running to the leader's point"),
            ["8. Squads|Share loot and meds"] = ("Share meds and loot", "Mates within 40 m pass things: to one bleeding without a bandage, wounded without a medkit, with a broken part without surgery - what is needed from whoever can share; with a full backpack - the best spare thing (10k+) to someone with room. The giver comes up, throws it into the hands, the other picks it up at once"),
            ["8. Squads|Voice callouts"] = ("Voice calls", "Squads talk to each other: cover me, covering, in position, ready, loot, copy, left/right flank, spread out, mate hurt"),
            ["8. Squads|Squad doctrines"] = ("Squad doctrines", "Every PMC squad (and solo) plays the raid its own way: assault, PvP hunters, looters, questers, carry, randoms, clan, boss hunters, quiet ones, long-range, speedrunners, armoured fist. One doctrine - at most two squads per raid; the numbers and two quirks of a squad are drawn again until the squad differs from all others; each fighter plays the doctrine his own way - by his style, skill, aggression, greed and weapon"),
            ["8. Squads|Squad playbook"] = ("Squad tactics deck", "In a fight the leader announces one of ten tactics: all-out assault, hold positions, base of fire and a flank, pincers, suppress and dash, bounding with cover, a pair forward, finish the wounded, fall back and regroup, everyone for himself. The choice - by doctrine, the state of the fight and what the squad has already done this raid (a repeat is rarer). Someone may go his own way, a newcomer picks up late"),
            ["8. Squads|Stop and listen"] = ("\"Stop, I heard that\"", "Hearing a fight the squad freezes for 3-6 s and turns to the sound, then decides (disciplined squads more often, randoms less)"),
            ["8. Squads|Squad comms"] = ("Squad comms", "The first to see an enemy announces the contact (direction, distance) - mates split off by QuestingBots learn of it in 0.5-3 s, silent squads are sometimes silent; a fallen mate - a vengeful squad goes for the killer, an unsteady one falls back (without a leader - soon to the exit); after a fight the leader waits a few seconds for the squad to gather; at a building entrance the rear holds the street for a couple of seconds"),
            ["8. Squads|Peek to draw fire"] = ("Peek to draw fire", "A card of the tactics deck: one fighter peeks 3-4 times for half a second and hides so that the enemy gives himself away by shooting, the others hold his position. Not always drawn"),
            ["8. Squads|Turn to a third party"] = ("Turn to a third party", "A card of the tactics deck: the squad is fired on from a new direction (not from its enemy's side) - half the squad turns there, the rest hold the former enemy"),
            ["8. Squads|Smoke screens"] = ("Smoke screens", "A card of the tactics deck and the fall back: a fighter with a smoke grenade puts up a screen between the squad and the enemy - the squad goes forward or falls back under it; in a fall back and at a fallen mate's body with an enemy near, it may also throw smoke"),
            ["8. Squads|Boss hunts"] = ("Boss hunts", "Squads of the \"Boss hunters\" doctrine always, part of the assault, PvP hunters, armoured fist and clan go for the map's boss in the 2nd-8th minute: they approach in two or three stages, the fight is SAIN's; they drop the hunt on a wounded leader, on losing half the squad or after 14 min; the killed boss and guards are searched. The bosses themselves do not change"),
            ["8. Squads|Flank in fights"] = ("Flanks in fights", "SAIN sends nobody round. In a fight gone quiet (the enemy is known but not seen) a squad may send one - point, rusher or hunter - round the flank by a hidden way while the rest hold the enemy; well-knit squads of 4+ sometimes take from two sides. A bold solo may go round on its own. Any contact - SAIN again"),
            ["8. Squads|Spread out in fights"] = ("Spread out in fights", "Two of the squad hitting one enemy from one point (within 2.5 m): one dashes to another cover so that a grenade or a burst does not cover both"),
            ["8. Squads|React to a fallen squadmate"] = ("Answer for a fallen mate", "When a mate is killed the others roughly know where the killer is: the bold go to trade, the rest hold and watch that way"),
            ["9. Combat morale|Combat morale"] = ("Combat morale", "Each bot weighs enemies and friends, wounds, losses, suppression and its own nerve. Winning - presses. Pinned or bleeding - changes position. Losing - falls back to cover. Broken - breaks contact and runs, then heals"),
            ["9. Combat morale|Smooth combat decisions"] = ("Smooth combat decisions", "SAIN re-decides 10 times a second and finishes nothing. Here a manoeuvre holds for a moment (search/dash 2.5 s, cover 1.8, stand and shoot 1.2, freeze 1) unless something urgent happened (a grenade, melee, falling back), the enemy appeared or vanished, the bot is wounded"),
            ["9. Combat morale|Respond to gunfire"] = ("Respond to gunfire", "Bots hear firefights (yours too) from afar and decide by character, kit and danger: burst in, approach, go round, lie low and listen, leave or ignore. Only leaders and solos react, a few bots per fight, with pauses"),
            ["9. Combat morale|Respond to noise"] = ("Respond to noise", "Bots hear more than gunfire: running (38 m), steps (14 m), a door (30 m), looting (14 m), reloading (16 m); a wall halves it, another floor more. A calm leader or solo goes to look, goes round, freezes to listen for a couple of seconds, leaves quietly or ignores - by character and doctrine. Your noise is heard the same way - you are looked for"),
            ["9. Combat morale|Fight like a player"] = ("Fight like a player", "After a few shots from one point (pro 4-9, newcomer 18-30, long gun 2-4) a fighter changes angle instead of peeking where he is expected; hit in the open from afar - runs to cover instead of standing; an expensive kit and a backpack of loot - more careful (fewer others' fights, less stubbornness), a bum has nothing to lose - bolder; a looter, a rat, a quiet squad do not start a firefight with a far AI scav that is not shooting at them"),
            ["9. Combat morale|Grenades like a player"] = ("Grenades like a player", "Everyone has a habit of his own: a pause of 10-60 s after a throw (assault almost without a pause, rats and looters save the grenade, a newcomer forgets); when the squad goes in to storm (all-out assault, building storm, tripwire and storm, bait, revenge) each may throw one at once. Where and whether it can be thrown - SAIN decides"),
            ["9. Combat morale|Stims before a storm"] = ("Stim before a storm", "Bold fighters of a squad's assault call with a stimulator in the bag inject it before the storm (a third of the time); the badly wounded - as before, SAIN decides"),
            ["9. Combat morale|Night discipline"] = ("Night discipline", "At night a disciplined fighter switches the flashlight off when an enemy, noise or a far fight is near (and in ambush) and skirts open ground. In close contact (within 70 m, shooting has begun) many switch the light on to blind the enemy. Discipline is a trait: some have it, some do not"),
            ["9. Combat morale|Gunfire hearing range x"] = ("Gunfire hearing range, x", "A multiplier of the range at which a shot is heard (SAIN's range; suppressors stay quiet). 300 m at most"),
            ["9. Combat morale|PMC squads always hostile"] = ("PMCs hostile to everyone", "Like online, a PMC squad is the enemy of every other PMC squad, its own side included (BEAR-BEAR, USEC-USEC). Squad mates are friends"),
            ["9. Combat morale|Distant fights are not my fight (m)"] = ("Far fights are not my fight, m", "SAIN counts as an enemy everyone it has heard of, and bots stood in a fight for minutes because of a firefight 250 m away. Beyond this an enemy the bot has not seen for a minute and who is not shooting at it is handed to \"Respond to gunfire\". 0 = as in SAIN"),
            ["9. Combat morale|Leave a lost fight"] = ("Leave a lost fight", "A bot against a clear odds (more enemies, only one left, wounded, pinned, worse gear) may lose its nerve and leave, forgetting the fight for a minute or two. Never for certain: a small chance that grows with pressure, higher for the timid, lower for the bold, and never with an enemy closer than 12 m"),
            ["9. Combat morale|Leave a lost fight: chance x"] = ("Chance to leave a fight, x", "A multiplier of how readily bots leave a lost fight (0.2 - very rarely, 3 - often)"),
            ["9. Combat morale|Lose interest in a cold fight"] = ("Forget a cold fight", "SAIN keeps an enemy \"known\" while the bot looks for him, and a bot that had seen nobody for minutes crept after a ghost to the end of the raid. Here, when nobody is in sight and nobody has shot for the whole stock of patience (rat 20-45 s, most 35-65, rusher 55-95, hunter 70-125), the enemy is forgotten for 1.5-3 minutes. A new glimpse, shot or hit brings the fight back. Also: an enemy close by but unseen and silent for a stretch (a standoff through a wall) no longer counts as contact"),
            ["9. Combat morale|Boss guards forget cold fights and get unstuck"] = ("Boss guards do not stand like posts", "Boss guards (Reshala, Gluhar and the like) get what PMCs and scavs get: they forget an enemy not seen for minutes and SAIN heals them again; a guard stuck on the move is moved. Raid 17:08: Vitek Zavodskoy stood 6 minutes in cover by the dorms and bled out from 33 % to 2 % keeping an enemy 100-160 m away \"in mind\""),
            ["9. Combat morale|Cold fight patience x"] = ("Search patience, x", "A multiplier of how long a bot looks for a lost enemy"),
            ["9. Combat morale|Search at full pace"] = ("Search at a normal pace", "SAIN's search crept (half-way crouched, a quarter in the \"stealthy\") and stood 1-4 s at each point. Here the bot searches for the enemy at a normal pace standing tall and looks around for under a second"),
            ["9. Combat morale|Fights on another floor are not my fight"] = ("A fight on another floor is not mine", "A fight above or below the bot (3+ m in height, no line of fire, nobody shooting at the bot) does not keep an enemy \"known\" and does not drive it to cover or to the shooting. Stairs and shots at the bot - at once"),
            ["9. Combat morale|Only fighters react to far shooting"] = ("Only fighters react to far shooting", "The range of reaction to gunfire depends on the bot: rushers and hunters ~170 m, snipers ~200, most 60-110, scavs less, those busy with loot or a quest less still. Off: anyone who hears reacts"),
            ["9. Combat morale|Return fire"] = ("Return fire", "A bot with an enemy in sight shoots instead of running: saw an enemy for 2.5 s at 80 m and did not shoot for 5 s - stands and shoots; could not get through - holds the place 12 s; breaking contact ends when the enemy is in sight closer than 25 m or there is nowhere to run"),
            ["9. Combat morale|Fight at the range of the gun"] = ("Fight at the gun's range", "A bot whose weapon does not reach the enemy (beyond the effective range of its type from the game plus a margin, or a bolt-action closer than 20 m / a marksman rifle closer than 15 m) takes another gun if that one reaches, and without it closes in with a dash, goes round, gets out of sight or drops the enemy (by character, health and numbers)"),
            ["9. Combat morale|Sidearm kept loaded"] = ("Sidearm always loaded", "Nobody loaded an empty pistol in the holster (the game loads only the weapon in hand): in a lull the bot takes it out, reloads and puts it away. If the pistol ran empty in close combat the bot reloads it instead of taking a bolt-action or marksman rifle that is worse at this range (up to 8 s, then as usual)"),
            ["9. Combat morale|No dogfight with far enemies"] = ("No close fight with a far enemy", "SAIN starts a \"close fight\" (stand, strafe, shoot - no cover) when the path to the enemy is shorter than 10 m, but if no path was built it counts its length as 0 - and the bot stood for hours in a \"close fight\" with an enemy 100 m away. A path shorter than the straight line to the same point does not count as a path here"),
            ["9. Combat morale|Bots see and shoot through bushes at each other"] = ("Bushes between bots", "In SAIN a bush fully blocks both sight and a shot, grass blocks a shot. Between two bots (not against you): closer than 25 m a bush does not hide (noticing still takes time), grass - closer than 10 m; through foliage a bot shoots closer than 25 m, and at one seen in the last 3 s - up to 60 m; through grass - up to 30 m"),
            ["9. Combat morale|Effective range margin, m"] = ("Range margin, m", "An addition to the effective range for the types below. A type's range is the top of the effective ranges of its guns in the game: shotgun 100 m, pistol 70, SMG 500, carbine 400, assault rifle 900, marksman rifle 1000, bolt-action 1000, machine gun 800. 0 = no margin"),
            ["9. Combat morale|Effective range margin for"] = ("Range margin applies to", "Weapon types with a margin, comma-separated: pistol, sniperRifle (bolt-action), assaultRifle, marksmanRifle, assaultCarbine, smg, shotgun, machinegun. The rest - the game's range as it is"),
            ["9. Combat morale|Long gun holds its position"] = ("Long gun holds its position", "A bot with a sniper or marksman rifle (or a sniper by style) does not step back or \"go looking\" while the enemies are farther than 35 m and it is healthy: it shoots from where it stands"),
            ["9. Combat morale|Notice an enemy right next to you"] = ("Notice an enemy right next to it", "An enemy at 5 m (or moving at 10 m) on the same floor with an open line is noticed in 1-2.5 s (by skill), as a player hears him and sees him from the corner of the eye. A bot busy with loot or a quest used to give an enemy a minute to stand behind its back"),
            ["9. Combat morale|Reload under fire"] = ("Reload under fire", "Caught by a close enemy in the middle of a long reload (a magazine over 30 or 4+ rounds into a tube): with a loaded pistol or a second gun - swaps, point blank - the knife, the rest reload while running to cover. The experienced more often than newcomers. Nobody presses or stands shooting while reloading"),
            ["9. Combat morale|Knife only at arms length"] = ("Knife only at arm's length", "The knife is only for an enemy within 3 m or when no gun has a round; with the knife and a far (or vanished) enemy the bot takes a gun with ammo at once. SAIN ran with the knife at any distance"),
            ["9. Combat morale|Fight roles"] = ("Fight roles", "Each bot in a fight takes a role - assault, flank or hold - by character, health and above all numbers: two against one - even a looter presses, one against two - even a rusher holds. Off: only rushers and hunters press"),
            ["9. Combat morale|Heal at the first quiet moment"] = ("Heal at the first quiet moment", "A wounded bot that is not being shot at now (no enemy in sight, no hits for a few seconds) bandages at once and orders do not break it off. SAIN began healing only when all enemies had cooled - bots with medkits in the backpack bled out"),
            ["9. Combat morale|Stop treatment when shot at"] = ("Stop treatment when shot at", "A bot breaks off a bandage, injection or operation like a player (right mouse button): fire, a hit, an enemy in sight within 50 m or known within 12 m - the animation is interrupted, nothing is used up, the gun is in hand again. While healing goes on, another weapon swap does not break it"),
            ["9. Combat morale|Treat a broken leg"] = ("Treat a broken leg", "With a broken or blacked leg and no painkiller EFT forbids running and cuts speed to 30 %, and EFT bots do not apply splints. Here the bot in quiet puts on a splint (or takes a painkiller if there is no splint or the leg is blacked); nothing to use - a mate passes it"),
            ["9. Combat morale|Run on a hurt leg only when it must"] = ("Run on a hurt leg only when needed", "On a painkiller a bot with a hurt leg can run again, and every second hits the leg. Here it walks at a normal pace and runs in dashes only when needed (broken - on a hit, fire, an enemy close, up to 4 s; blacked - only on a hit or fire, up to 2.5 s)"),
            ["9. Combat morale|Surgery with a kit from the bag"] = ("Surgery with a kit from the bag", "A bot restores a blacked part with a surgical kit (CMS, Surv12) from the backpack, rig or pockets, found in the raid. EFT looked for a kit only in the pouch - PMCs did not operate"),
            ["9. Combat morale|Only a medkit that can stop the bleeding"] = ("A medkit that will stop the bleeding", "EFT bots took the first medkit able to stop bleeding, even with a remainder that would not be enough, and used it every 5 s until death. Here a medkit with a margin is taken; without one the bot heals what it can, and a useless treatment is not repeated twice in a row for 45 s"),
            ["9. Combat morale|Surgery only when safe"] = ("Surgery only when safe", "SAIN started an \"operation\" with any known enemy and dropped it a tick later, and again 2 s after - every start stopped the bot for 3 s and the wounded froze for minutes under fire. Here an operation begins only when the situation is clear. Off: as in SAIN"),
            ["9. Combat morale|Patch up and fight before heading out"] = ("Fight and patch up before leaving", "EFT's path to the exit was highest of all: a bot left bleeding, with an empty gun, past a shooting enemy. Here first come an enemy within 60 m, bleeding or a heavy wound that can be treated, and a broken leg that can be splinted (up to 45 s at a time)"),
            ["4. Bot characters|No jumping on broken legs"] = ("No jumping on broken legs", "A bot with a broken or blacked leg does not jump (SAIN's dashes, QuestingBots' unsticking, LiveRaid's routes) - the landing hits the leg again"),
            ["9. Combat morale|Keep emptied magazines"] = ("Do not throw magazines away", "After a reload EFT puts the empty magazine into the rig or pockets, and if they are full - throws it on the ground. A bot with a full rig lost a magazine on every reload (Reshala's guard aimed and did not shoot). Here the empty one goes to the backpack or pouch, and unreachable magazines return to the rig and are loaded"),
            ["9. Combat morale|Bottomless ammo"] = ("Ammo from nowhere", "Off = as in SPT: only what the bot was issued. On: when there is nothing to load an empty magazine with, a loose stack is summoned (PMCs - only into the secure container, scavs - into the rig or a pocket), a new stack when the old one is used up; rounds found in the raid do not count. For the weapon the bot began the raid with no magazines are made; for a found one - one spare, if the bot has no magazines for it. Reloading goes as usual, with the animation and time"),
            ["9. Combat morale|Summoned rounds per stack"] = ("Rounds in a summoned stack, at most", "A loose stack is from this number minus 10 up to this number (30-40 by default)"),
            ["9. Combat morale|Summoned items give way"] = ("Summoned items give way to loot", "Summoned rounds and magazines do not count as used backpack slots (the bot is not \"full\" because of them) and are removed when loot lacks room"),
            ["9. Combat morale|Watch for aiming without a shot"] = ("Watch for aiming without a shot", "Any bot (bosses and guards too) that held an enemy in sight and in reach for 6 s without a shot: empty or not chambered - reloads, a hung reload - cleared, the state of hands, gun and magazines - to the log (\"LR Weapon: ... aims at ... without a shot\")"),
            ["9. Combat morale|Free stuck hands"] = ("Free stuck hands", "EFT clears \"reloading\" only at the end of the animation; if a medkit, a weapon swap or looting interrupted it, the flag hangs for ever: the bot does not shoot, swap weapons or heal. Here the hanging flag is cleared, empty hands get the gun back, an unfinished swap is released"),
            ["9. Combat morale|Steady weapon handling"] = ("Steady weapon swaps", "LootingBots took the main gun after every looted thing, EFT / SAIN / LootingBots each swapped weapons on their own. A bot that swapped 3 times in 15 s keeps the current gun for 12 s; EFT's chance to swap instead of reloading is cut from 80 % to 35 %"),
            ["9. Combat morale|Squadmates are never enemies"] = ("Mates are never enemies", "A bot never counts as an enemy a mate it spawned with, whatever happens to the groups later. QuestingBots split off a bot that had not healed in 2 minutes into a group of its own, and EFT counted it a foreign PMC - DeadW0Lf shot his own leader from 4 m"),
            ["10. Quests and routes|Head for the task"] = ("Head for the quest step", "A PMC that got a quest step (or hangs about one for long) mostly goes to it like a player on a task: stops for what lies right on the way (12 m) and for bodies, mates loot only close by, the looter is waited for no more than ~45 s instead of 2-3 min"),
            ["10. Quests and routes|Squads spread over quests"] = ("Squads spread over quests", "A quest already held by other PMC squads is less wanted - by half for every such squad - and squads go different ways instead of six into one district"),
            ["10. Quests and routes|Give up a quest step after (min)"] = ("Give up a quest step after, min", "A PMC that held one quest step this long without doing it (fights do not count) drops it and takes another; each has 75-130 % of this. 0 = never. Also: a step the bot has come no closer to by 20 m in 2.5 minutes (outside fights and looting) is dropped"),
            ["10. Quests and routes|Check quest objectives"] = ("Check quest objectives", "At raid start check every EFT quest objective of the map: whether QuestingBots has a point, whether bots can reach it, whether the point is in place. The result is in the log (LR Quests on <map>) and questaccess/<map>.csv"),
            ["10. Quests and routes|Fix quest points"] = ("Fix quest points", "If QuestingBots put a quest point outside its zone or on another floor, move it to the real place (a reachable floor in the zone / beside the item). Locked rooms get a door assigned"),
            ["10. Quests and routes|Act out quest objectives"] = ("Act out quest objectives", "A PMC on an EFT quest acts it out like a player: crouches and picks up the quest item (the item stays), plants a marker for the planting time, looks around on the spot. Only then is the objective counted"),
            ["10. Quests and routes|Quest hand animations"] = ("Hand animations in quests", "The \"take / put\" animation during quest objectives (turn off if a bot's hands get stuck)"),
            ["10. Quests and routes|Routes through blocked places"] = ("Routes through blocked places", "Recorded routes BepInEx/plugins/LiveRaid/routes/<map>.json: bots climb over rubble, walk along railings where the navmesh does not lead. From the next raid"),
            ["10. Quests and routes|Skip the climb when nobody sees it"] = ("Skip the climb when nobody sees", "A bot that nobody sees is moved at once to the end of the route; one that is seen climbs point by point"),
            ["10. Quests and routes|Bots sent up a route per raid"] = ("Bots per route per raid", "Places reached only by a route (the \"Cliff\" on Customs) get goals for no more than this many different bots per raid. 0 = nobody"),
            ["10. Quests and routes|Use learned shortcuts"] = ("Use learned shortcuts", "Experimental. Climbs from your routes (learned/<map>.shortcuts.json) become routes like recorded ones. Look the file over first - you may have climbed where bots should not go"),
            ["10. Quests and routes|Route recorder"] = ("Route recorder", "Record a route yourself: stand before the obstacle and press \"Point\", press at every support (crouch - a low point, \"Jump point\" - where a jump is needed), finish on the floor behind the obstacle and press \"Save\". The route works at once"),
            ["10. Quests and routes|Record point"] = ("Route: point", "Record a route point"),
            ["10. Quests and routes|Record jump point"] = ("Route: jump point", "Record a point with a jump"),
            ["10. Quests and routes|Remove last point"] = ("Route: remove point", "Remove the last point"),
            ["10. Quests and routes|Save route"] = ("Route: save", "Save the route"),
            ["5. Performance|Simplify distant bots"] = ("Simplify distant bots", "On: bots far from you and not in a fight \"think\" less often (SAIN's sight and decisions), but move, quest, loot and leave - nobody sleeps. Off: every bot is full-fledged at any distance (heavier on the CPU)"),
            ["5. Performance|Allow QuestingBots to put far bots to sleep"] = ("Let QuestingBots put far bots to sleep", "Off (LiveRaid): nobody sleeps - far bots move, quest, loot and fight, only think less often. On: QuestingBots' limiter (its F12 and distances) may freeze far bots completely. Lighter on the CPU"),
            ["5. Performance|Far bots see and hear each other"] = ("Far bots see and hear each other", "On (like online): bots fight each other at full range over the whole map. Off: SAIN's \"AI vs AI\" limits - away from you bots see each other only at 200 / 100 / 50 m and hear at 100 / 60 / 25 m, far squads walk past each other. Slightly lighter on the CPU"),
            ["11. After death|Free camera after death"] = ("Free camera after death", "When you die the raid does not end: a free camera flies over the map and you watch the bots. The raid ends with the \"End raid\" key (bottom left) or by time. The outcome is always your death: nothing after it goes to the profile"),
            ["11. After death|Start raids as an observer"] = ("Start raids as an observer", "On: you do not play the raid - it begins at once in the free camera (watch the bots, take over, the End key). Your character is out of the game: hidden, unharmed, nobody sees it. The raid does not count: gear as it was, no experience, no statistics (needs the LiveRaid server mod). From the next raid"),
            ["11. After death|Follow a random PMC at the start"] = ("Follow a random PMC at the start", "Works with \"Start raids as an observer\". As soon as a PMC appears in the raid the camera jumps to a random one and follows it, as with the \"Follow bot\" key. Free flight (WASD) cancels following, \"Next bot\" switches. No PMC in the first minute - the free camera stays"),
            ["11. After death|Take over a bot"] = ("Take over a bot (raw mode)", "EXPERIMENTAL, OFF BY DEFAULT, THIS MODE IS RAW AND OFTEN BREAKS: after the bot you play dies, the textures of the location may stop loading, sound may go wrong and other things may fail - you may have to restart the game. Turn it on at your own risk. In the free camera aim at a bot and press \"Take over\" - you play it until it dies or leaves. Its kills, loot and exit do not go to the profile"),
            ["11. After death|End the raid when the taken bot dies"] = ("End the raid when the bot dies", "Off: back to the free camera, you can take over another. On: the raid ends at once"),
            ["11. After death|Bot names in the free camera"] = ("Bot names in the camera", "Small name tags above bots in view (up to 150 m) in the free camera"),
            ["11. After death|Free camera speed (m/s)"] = ("Camera speed, m/s", "Base speed; Shift x4, Alt x0.25, the mouse wheel changes it in flight"),
            ["11. After death|End raid"] = ("End raid", "End the raid as your death (from the free camera or from a bot)"),
            ["11. After death|Take over"] = ("Take over", "Take over the bot in the screen centre (or the one you follow)"),
            ["11. After death|Leave the bot"] = ("Leave the bot", "Give the bot back to its AI and return to the free camera"),
            ["11. After death|Follow bot"] = ("Follow bot", "Fly after the bot in the screen centre (mouse - around it, wheel - distance); WASD - free flight again"),
            ["11. After death|Next bot"] = ("Next bot", "Follow the next living bot (the nearest first)"),
            ["11. After death|Watch through the bot eyes"] = ("Through the bot's eyes", "While following (without taking over): the camera behind the bot or through its eyes"),
            ["0. Compact menu|Language"] = ("Language / Язык", "Language of the F12 texts and the free camera hints. Auto - the game's own interface language (Russian gets Russian, every other language gets English). Reopen F12 to see the translation"),
            ["0. Compact menu|Preset"] = ("Ready-made sets of settings", "Ready-made sets, so that nobody has to go through two hundred settings. Recommended - as the author meant it: all packs on, population and performance at their defaults. Weak PC - far bots simplified and put to sleep, AI versus AI only close by, fewer bots, no detailed logs. Quiet raids - fewer bots and PMCs, a lower crowd cap. Busy raids - more bots and PMCs, more reserves, more fights. Fixes only - all of LiveRaid's behaviour is off, only the repairs of EFT's bugs and healing stay. Custom - your own values (every setting is shown). In LiveRaid Online only the host chooses"),
            ["1. Main|Enabled"] = ("Enable LiveRaid", "The mod's main switch (needs a game restart)"),
        };
    }
}
